test('ISSUE-214: buildUrl keeps retry=0 and include_archived=false', () => {
  const url = buildUrl({
    baseUrl: 'https://api.example.test',
    path: ['webhooks', 'deliveries'],
    query: { retry: 0, include_archived: false, dry_run: true }
  });
  assert.equal(
    url,
    'https://api.example.test/webhooks/deliveries?dry_run=true&include_archived=false&retry=0'
  );
});

test('ISSUE-214: null, undefined and empty-string query values are still omitted; zero/false array items kept', () => {
  const url = buildUrl({
    baseUrl: 'https://api.example.test',
    query: { a: null, b: undefined, c: '', d: [0, false, null, 1] }
  });
  assert.equal(url, 'https://api.example.test/?d=0&d=false&d=1');
});
